  "Puntos de esta semana y del total con este clan. Toca a un miembro para ver su perfil.": "Punkte dieser Woche und insgesamt mit diesem Clan. Tippe auf ein Mitglied, um sein Profil zu sehen.",
  "Toca para seguir": "Tippen zum Fortfahren",
  "por": "von",
  "La GTS es un banco online de futbolistas: dejas una copia repetida pidiendo otro futbolista a cambio, y cualquiera que tenga el que pides puede cambiártelo aunque no estés conectado.": "Die GTS ist eine Online-Spielerbank: Du hinterlegst ein Duplikat und wünschst dir dafür einen anderen Spieler, und jeder, der den gewünschten hat, kann tauschen, auch wenn du offline bist.",
  "Para usarla tienes que entrar con tu cuenta.": "Dafür musst du dich mit deinem Konto anmelden.",
  "Ir a Perfil para entrar": "Zum Profil, um dich anzumelden",
  "Recuperar": "Zurückholen",
  "Dejar un futbolista": "Spieler hinterlegen",
  "Solo copias repetidas": "Nur Duplikate",
  "Mejora la «Ventanilla GTS» en Mejoras": "Verbessere den „GTS-Schalter“ unter Verbesserungen",
  "Huecos: {openLength}/{slots}. La copia que dejas va sin entrenamiento, estrellas ni ascensión: tu futbolista se queda con todo. Un HÉROE ascendido sí puede dejar sus copias repetidas. No se pueden dejar Leyenda ni futbolistas de evento, ni repetir un cambio.": "Plätze: {openLength}/{slots}. Die hinterlegte Kopie geht ohne Training, Sterne oder Aufstieg: Dein Spieler behält alles. Ein aufgestiegener HELD kann seine Duplikate hinterlegen. Legenden und Event-Spieler können nicht hinterlegt und ein Tausch nicht wiederholt werden.",
  "Buscar futbolista (el que quieres o el que piden)": "Spieler suchen (den du willst oder den gewünschten)",
  "Solo los que puedo cambiar": "Nur die, die ich tauschen kann",
  "↻ Actualizar": "↻ Aktualisieren",
  "{username} deja": "{username} hinterlegt",
  "Estación Global de Intercambio": "Globale Tauschstation",
  "Deja una copia repetida, pide el futbolista que te falta y recoge tu cambio cuando vuelvas.": "Hinterlege ein Duplikat, wünsch dir den Spieler, der dir fehlt, und hol deinen Tausch ab, wenn du zurück bist.",
  "Ese depósito ya no está: puede que alguien te lo acabe de cambiar.": "Dieses Angebot gibt es nicht mehr: Vielleicht hat es gerade jemand getauscht.",
  "No se pudo cargar la GTS.": "Die GTS konnte nicht geladen werden.",
  "Buscar por nombre": "Nach Namen suchen",
  "¡Gracias por ayudar!": "Danke für deine Hilfe!",
  "+{total} fichas": "+{total} Marken",
  "Cada bug que reportes y se corrija te da 100 fichas. Repórtalos desde el 🐞 del menú o en Ajustes.": "Jeder gemeldete Bug, der behoben wird, bringt dir 100 Marken. Melde sie über den 🐞 im Menü oder in den Einstellungen.",
  "Ver": "Ansehen",
