  "Necesitas conexión para reclamar el pase (hora del servidor).": "Du brauchst eine Verbindung, um den Pass abzuholen (Serverzeit).",
  "Cuenta online": "Online-Konto",
  "El servicio online no está activado en esta versión. Tu progreso se guarda en este navegador (Ajustes » Exportar/Importar para llevarlo a otro). Con el servicio activo podrás entrar con Google, reservar tu nombre en todo el mundo, aparecer en el ranking global y guardar en la nube.": "Der Online-Dienst ist in dieser Version nicht aktiv. Dein Fortschritt wird in diesem Browser gespeichert (Einstellungen » Exportieren/Importieren, um ihn mitzunehmen). Mit aktivem Dienst kannst du dich mit Google anmelden, deinen weltweiten Namen sichern, in der globalen Rangliste erscheinen und in der Cloud speichern.",
  "Estás jugando como invitado: tu progreso se guarda solo en este navegador. Entra con Google para reservar tu nombre en todo el mundo, aparecer en el ranking y guardar en la nube. Tu correo es privado: nunca aparece en el ranking.": "Du spielst als Gast: Dein Fortschritt wird nur in diesem Browser gespeichert. Melde dich mit Google an, um deinen weltweiten Namen zu sichern, in der Rangliste zu erscheinen und in der Cloud zu speichern. Deine E-Mail ist privat: Sie erscheint nie in der Rangliste.",
  "Nombre global: <b>{onlineName}</b> (permanente)": "Weltweiter Name: <b>{onlineName}</b> (dauerhaft)",
  "Reserva tu nombre global. Si «{profileName}» ya está ocupado, elige otro: tu progreso no se toca.": "Sichere deinen weltweiten Namen. Ist „{profileName}“ schon vergeben, wähle einen anderen: Dein Fortschritt bleibt unberührt.",
  "Reservar nombre": "Namen sichern",
