  "Cuenta tu mejor marca en la clasificación general (por puntos). Al terminar la temporada, los premios te llegan al entrar en el juego y el ranking empieza de cero.": "Es zählt dein bester Rekord in der Gesamtwertung (nach Punkten). Am Saisonende bekommst du die Preise beim Öffnen des Spiels und die Rangliste startet bei null.",
