  "PREMIUM": "PREMIUM",
  "Las llaves y los niveles son de esta temporada: cuando termine, empieza una nueva con su propio pase. La EXP cuenta aunque no tengas llave: al abrir una fila puedes reclamar todo lo que ya hayas alcanzado.": "Schlüssel und Level gehören zu dieser Saison: Wenn sie endet, beginnt eine neue mit eigenem Pass. EXP zählt auch ohne Schlüssel: Wenn du eine Reihe öffnest, kannst du alles abholen, was du schon erreicht hast.",
