  "Partidas por día, horas, arenas, rangos y capitanes salen de las partidas enviadas al ranking (solo cuentas con sesión; los invitados no cuentan). Arenas, rangos y capitanes son de todo el historial.": "Runden pro Tag, Stunden, Arenen, Ränge und Kapitäne stammen aus den an die Rangliste gesendeten Runden (nur angemeldete Konten; Gäste zählen nicht). Arenen, Ränge und Kapitäne umfassen den ganzen Verlauf.",
  "Espíritus guerreros": "Kampfgeister",
  "Sin datos todavía: se cuentan las partidas terminadas desde la 2.02.": "Noch keine Daten: Gezählt werden Runden, die seit 2.02 beendet wurden.",
  "Espíritus más usados": "Meistgenutzte Geister",
