  "Cuenta el espíritu activo del equipo (el primero por la izquierda) en cada partida terminada con sesión iniciada. El daño es el que hace el equipo en los 3 s siguientes a cada ulti.": "Gezählt wird der aktive Geist des Teams (der erste von links) in jeder Runde, die angemeldet beendet wurde. Der Schaden ist der, den das Team in den 3 s nach jeder Ulti macht.",
