  "Al responder, o al marcarlo como corregido o descartado, el jugador recibe un aviso. Las notas privadas nunca las ve.": "Wenn du antwortest oder es als behoben oder verworfen markierst, bekommt der Spieler einen Hinweis. Die privaten Notizen sieht er nie.",
