  "Para celebrarlo abrimos el <b>Banner de agradecimiento</b> durante {days} días: Ataque a los Titanes, Los Siete Pecados Capitales y Axel Encapuchado, solo aquí.": "Zur Feier öffnen wir für {days} Tage das <b>Dankeschön-Banner</b>: Attack on Titan, The Seven Deadly Sins und Axel mit Kapuze, nur hier.",
  "Se tira con <b>fichas de evento</b>: cada partida en <b>Rango S o X</b> te da tantas como fichas normales. {cost} la tirada, {multiCost} el ×10.": "Gezogen wird mit <b>Event-Marken</b>: Jede Runde auf <b>Rang S oder X</b> gibt dir so viele wie normale Marken. {cost} pro Zug, {multiCost} für ×10.",
