  "✦ DEL AURA": "✦ VON DER AURA",
  "Tienes <b>5 equipos</b>: cambia entre ellos arriba. Elige <b>7 candidatos</b>. Empiezas solo con el <b>capitán</b>; al subir de nivel podrás fichar a los otros seis (máximo {MAX_TEAM} en el campo). Pulsa un futbolista de tu colección para añadirlo o quitarlo, pulsa una plaza para cambiarla, o arrastra para colocar e intercambiar. Se guarda solo.": "Du hast <b>5 Teams</b>: Wechsle oben zwischen ihnen. Wähle <b>7 Kandidaten</b>. Du startest nur mit dem <b>Kapitän</b>; beim Aufsteigen kannst du die anderen sechs verpflichten (bis zu {MAX_TEAM} auf dem Platz). Tippe auf einen Spieler deiner Sammlung, um ihn hinzuzufügen oder zu entfernen, tippe auf einen Platz, um ihn zu tauschen, oder ziehe zum Platzieren und Tauschen. Wird automatisch gespeichert.",
