  "Abre la fila normal del pase de {sdName}: monedas, fichas, tiradas, los jugadores del Dominio de Zanark, banners y un marco.": "Öffnet die normale Reihe des Passes {sdName}: Münzen, Marken, Züge, die Spieler von Zanarks Domäne, Banner und einen Rahmen.",
