  "¡RECLAMAR!": "ABHOLEN!",
  "Elige el uniforme de tu escuadra: cambia el cuerpo y conserva la cabeza original y todas las animaciones. Se consiguen con las recompensas de equipo de la Enciclopedia.": "Wähle das Trikot deines Teams: Es ändert den Körper und behält den Originalkopf und alle Animationen. Du bekommst sie über die Team-Belohnungen der Enzyklopädie.",
