  "Entrenamiento {used}/{tmax}": "Training {used}/{tmax}",
  "Fichas de entrenamiento: <b>{have}</b>": "Trainingsmarken: <b>{have}</b>",
  "Devolver puntos": "Punkte zurückgeben",
  "Cada ficha suma 1 punto a la estadística que elijas (máximo {tmax} para este futbolista). Se ganan con victorias, rangos superados, supervivencia infinita, misiones semanales y logros.": "Jede Marke gibt 1 Punkt auf den Wert deiner Wahl (bis zu {tmax} für diesen Spieler). Du bekommst sie durch Siege, geschaffte Ränge, Endlos-Überleben, Wochenmissionen und Erfolge.",
  "Técnica de HÉROE:": "HELDEN-Technik:",
  "Pasiva:": "Passiv:",
  "(adaptación de InaZurvivors)": "(InaZurvivors-Anpassung)",
  "Talento:": "Talent:",
  "(efecto adaptado; sube con el nivel de la técnica)": "(angepasster Effekt; wächst mit dem Level der Technik)",
  "Repertorio (2 técnicas activas en combate)": "Repertoire (2 aktive Techniken im Kampf)",
  "☆ Empezar con esta": "☆ Mit dieser starten",
  "✦ Ver su Aura": "✦ Seine Aura ansehen",
  "{add} Aura": "{add} Aura",
  "Valores centrados en 60: por encima suman, por debajo restan. Cada técnica usa las estadísticas de su futbolista. Lo propio llega a 99; con un Aura, hasta {EFFECTIVE_STAT_MAX}.": "Werte um 60 zentriert: darüber addieren sie, darunter ziehen sie ab. Jede Technik nutzt die Werte ihres Spielers. Eigene Werte gehen bis 99; mit einer Aura bis {EFFECTIVE_STAT_MAX}.",
  "Banner de agradecimiento": "Dankeschön-Banner",
  "Ataque a los Titanes, Los Siete Pecados Capitales y Axel Encapuchado · {cost} fichas de evento la tirada": "Attack on Titan, The Seven Deadly Sins und Axel mit Kapuze · {cost} Event-Marken pro Zug",
  "InaZurvivors x BlueLock": "InaZurvivors x BlueLock",
  "Nagi e Isagi · {cost} fichas de evento la tirada": "Nagi und Isagi · {cost} Event-Marken pro Zug",
