  "(con un Épico o mejor asegurado) · ×100 cuesta": "(mit garantiert Episch oder besser) · ×100 kostet",
  "Jugar partidas (más si ganas)": "Runden spielen (mehr, wenn du gewinnst)",
  "Misiones diarias, semanales y logros": "Tägliche und wöchentliche Missionen und Erfolge",
  "Altares y fichas en el campo": "Altäre und Marken auf dem Platz",
  "Primera victoria en cada arena y rango": "Erster Sieg in jeder Arena und jedem Rang",
  "NUEVO": "NEU",
  ": se desbloquea para siempre y ya puede ir en Mi Equipo.": ": für immer freigeschaltet und jetzt in Mein Team einsetzbar.",
  "Duplicado": "Duplikat",
  ": sirve para ascender al futbolista; si ya no puede ascender más, se convierte en monedas.": ": dient zum Aufstieg des Spielers; kann er nicht mehr aufsteigen, wird es zu Münzen.",
  "Los duplicados también pagan la <b>ascensión</b> de cualquier futbolista (Fix 1.53): cada ascensión sube una rareza y cuesta según la rareza desde la que sube (Común {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Legendario {ascenso4}). Al llegar a Mítico, el HÉROE cuesta según la rareza con la que nació: Común {heroe}, Raro {heroe2}, Épico {heroe3}, Legendario {heroe4}, Mítico {heroe5} y Leyenda {heroe6}. Después, cada HÉROE gana hasta {HERO_STARS_MAX} estrellas de héroe (Mítico {estrella} duplicados cada una).": "Duplikate bezahlen auch den <b>Aufstieg</b> jedes Spielers: Jeder Aufstieg hebt die Seltenheit um eine Stufe und kostet je nach Ausgangsseltenheit (Gewöhnlich {ascenso}, Selten {ascenso2}, Episch {ascenso3}, Legendär {ascenso4}). Bei Mythisch kostet HELD je nach ursprünglicher Seltenheit: Gewöhnlich {heroe}, Selten {heroe2}, Episch {heroe3}, Legendär {heroe4}, Mythisch {heroe5} und Legende {heroe6}. Danach verdient jeder HELD bis zu {HERO_STARS_MAX} Heldensterne (Mythisch {estrella} Duplikate pro Stern).",
  "Con {MAX_STARS} estrellas y HÉROE, cada copia da monedas (de {comun} a {leyenda} según la rareza).": "Mit {MAX_STARS} Sternen und HELD gibt jede Kopie Münzen (von {comun} bis {leyenda} je nach Seltenheit).",
  "Fichas = máquina de cápsulas · Monedas = mejoras y tiendas. Gráficos de la máquina: Inazuma Eleven 3 (hoja de The Spriters Resource, ripeada por Avegaille), recurso local.": "Marken = Kapselmaschine · Münzen = Verbesserungen und Shops. Grafik der Maschine: Inazuma Eleven 3 (Sheet von The Spriters Resource, gerippt von Avegaille), lokale Ressource.",
  "Duplicado · +{refund} monedas": "Duplikat · +{refund} Münzen",
  "¡Estrella {starReady} lista! Súbela en su ficha": "Stern {starReady} bereit! Steigere ihn auf seiner Karte",
  "{title} · todo lo que has fichado": "{title} · alles, was du verpflichtet hast",
