  "BONIFICACIÓN DE {toUpperCase}": "BONUS {toUpperCase}",
  "Invertido: <b>{spentOn}</b> monedas · pulsa dos veces para confirmar cada compra": "Investiert: <b>{spentOn}</b> Münzen · zweimal tippen, um jeden Kauf zu bestätigen",
  "Reiniciar y recuperar todo": "Zurücksetzen und alles zurückbekommen",
