  "Rareza": "Seltenheit",
  "HÉROE": "HELD",
  "Tipo de técnica": "Technikart",
  "Por comprar": "Noch nicht gekauft",
  "REPERTORIO": "REPERTOIRE",
  "Cada futbolista solo usa su propio repertorio. Aquí desbloqueas sus técnicas y compras <b>manuales</b> de daño permanente (subir de nivel una técnica en partida es aparte).": "Jeder Spieler nutzt nur sein eigenes Repertoire. Hier schaltest du seine Techniken frei und kaufst dauerhafte Schadens-<b>Handbücher</b> (eine Technik in der Runde aufzuleveln ist etwas anderes).",
  "Bonificaciones para todo el equipo. No cambian la equipación Raimon que se ve en combate.": "Boni für das ganze Team. Sie ändern nicht das Raimon-Trikot, das im Kampf zu sehen ist.",
  "InaZurvivors — Proyecto de fans no oficial": "InaZurvivors — Inoffizielles Fanprojekt",
  "InaZurvivors es un fangame independiente y gratuito desarrollado por AstraStorm17, inspirado en la franquicia Inazuma Eleven.": "InaZurvivors ist ein kostenloses, unabhängiges Fangame von AstraStorm17, inspiriert von der Inazuma-Eleven-Reihe.",
  "Inazuma Eleven, sus personajes, nombres, diseños, logotipos, música y materiales originales son propiedad de LEVEL-5 y/o sus respectivos titulares.": "Inazuma Eleven, seine Figuren, Namen, Designs, Logos, Musik und Originalmaterialien sind Eigentum von LEVEL-5 und/oder den jeweiligen Rechteinhabern.",
  "Este proyecto no está afiliado, patrocinado ni aprobado por LEVEL-5.": "Dieses Projekt ist nicht mit LEVEL-5 verbunden und wird von LEVEL-5 weder gesponsert noch unterstützt.",
  "El código y los materiales originales desarrollados específicamente para InaZurvivors pertenecen a sus respectivos autores.": "Der Code und die eigens für InaZurvivors erstellten Originalmaterialien gehören ihren jeweiligen Urhebern.",
  "Los recursos gráficos y sonoros de terceros conservan sus derechos originales.": "Grafiken und Töne Dritter behalten ihre ursprünglichen Rechte.",
  "La inclusión de créditos y este aviso no implica la existencia de una licencia o autorización para distribuir material protegido.": "Die Nennung von Credits und dieser Hinweis bedeuten keine Lizenz oder Erlaubnis zur Verbreitung geschützten Materials.",
  "Desarrollo": "Entwicklung",
  "Diseño, dirección y desarrollo: AstraStorm17.": "Konzept, Leitung und Entwicklung: AstraStorm17.",
  "Programación con asistencia de Claude (Anthropic).": "Programmierung mit Unterstützung von Claude (Anthropic).",
  "Recursos de terceros y su procedencia": "Ressourcen Dritter und ihre Herkunft",
  "Futbolistas, retratos, cuerpos, escudos, objetos, arenas y música: Inazuma Eleven 2 (LEVEL-5), extraídos de una copia propia del juego.": "Spieler, Porträts, Körper, Wappen, Gegenstände, Arenen und Musik: Inazuma Eleven 2 (LEVEL-5), aus einer eigenen Kopie des Spiels extrahiert.",
  "Futbolistas, retratos y escudos de las sagas Mundial, GO, Chrono Stones, Galaxy, Ares y Orion: Inazuma Eleven 3 (LEVEL-5) con el parche de fans «Great Road of Heroes 3.1». Autoría del parche: no verificada; base y añadidos del parche no se pueden separar.": "Spieler, Porträts und Wappen der Sagas WM, GO, Chrono Stones, Galaxy, Ares und Orion: Inazuma Eleven 3 (LEVEL-5) mit dem Fan-Patch „Great Road of Heroes 3.1“. Urheberschaft des Patches: nicht überprüft; Basis und Ergänzungen des Patches lassen sich nicht trennen.",
  "Creados para InaZurvivors: efectos de supertécnicas, efectos de sonido, iconos de elemento, orbes, música «Generada» e interfaz.": "Für InaZurvivors erstellt: Effekte der Spezialtechniken, Soundeffekte, Element-Symbole, Kugeln, „Generierte“ Musik und Oberfläche.",
  "Redes sociales": "Soziale Netzwerke",
  "Sobre el desarrollador": "Über den Entwickler",
  "AstraStorm también ha creado otros videojuegos.": "AstraStorm hat auch andere Videospiele gemacht.",
  "Enlaces oficiales": "Offizielle Links",
  "Sin cuenta, InaZurvivors no recopila datos personales: tu progreso se guarda solo en este navegador. Con cuenta online (Google) se guardan tu correo de Google (privado), tu nombre, tus marcas y tu guardado.": "Ohne Konto sammelt InaZurvivors keine persönlichen Daten: Dein Fortschritt wird nur in diesem Browser gespeichert. Mit Online-Konto (Google) werden deine Google-E-Mail (privat), dein Name, deine Rekorde und dein Speicherstand gespeichert.",
  "{VERSION_LABEL} · compilación interna {BUILD}": "{VERSION_LABEL} · interner Build {BUILD}",
  "Música": "Musik",
  "Efectos": "Effekte",
  "Silenciar todo": "Alles stumm",
