  "Ver otra vez": "Nochmal ansehen",
  "Compartir mis partidas": "Meine Runden teilen",
  "Con la sesión iniciada, cada partida en solitario se graba (posiciones, técnicas y cartas, sin nada personal) para que el autor vea cómo se juega y equilibre el juego. Se guardan tus 3 últimas y las de tus marcas del ranking.": "Wenn du angemeldet bist, wird jede Solo-Runde aufgezeichnet (Positionen, Techniken und Karten, nichts Persönliches), damit der Entwickler sieht, wie gespielt wird, und das Spiel ausbalancieren kann. Gespeichert werden deine letzten 3 und die deiner Ranglisten-Rekorde.",
  "Copia de seguridad": "Sicherung",
