  "Empezar de cero": "Von vorn beginnen",
  "Reiniciar progreso…": "Fortschritt zurücksetzen…",
  "Controles: WASD/flechas mover · 1/2/3 formación · Esc/P pausa.": "Steuerung: WASD/Pfeiltasten bewegen · 1/2/3 Formation · Esc/P Pause.",
  "Copia exportada": "Sicherung exportiert",
