  "🔒 Para siempre": "🔒 Für immer",
  "Aún sin elegir": "Noch nicht gewählt",
  "Elige… (solo una vez)": "Wählen… (nur einmal)",
  "¿Seguro? {teamLabel} será tu equipo favorito para siempre. Elígelo otra vez para confirmar.": "Sicher? {teamLabel} wird für immer dein Lieblingsteam. Wähle es nochmal zur Bestätigung.",
  "{active}/{TRAIN_SLOTS} técnicas activas": "{active}/{TRAIN_SLOTS} aktive Techniken",
  "Prueba las técnicas de tus futbolistas al nivel que quieras, también las combinadas que puedan hacer juntos (con sus Auras incluidas). Nadie recibe daño y no se gana nada: ni recompensas, ni misiones, ni ranking.": "Teste die Techniken deiner Spieler auf jedem Level, auch die Kombi-Techniken, die sie zusammen können (Auren inklusive). Niemand bekommt Schaden und man gewinnt nichts: keine Belohnungen, keine Missionen, keine Rangliste.",
