  "¡JEFE DERROTADO!": "BOSS BESIEGT!",
  "La victoria ya es tuya. ¿Terminas aquí o sigues sobreviviendo?": "Der Sieg gehört dir. Hörst du hier auf oder überlebst du weiter?",
  "TERMINAR PARTIDA": "RUNDE BEENDEN",
  "Victoria y recompensas ahora": "Sieg und Belohnungen jetzt",
  "CONTINUAR SOBREVIVIENDO": "WEITER ÜBERLEBEN",
  "Cinco fases hasta el Infierno. Cada minuto jugado da recompensa y los jefes regresan.": "Fünf Phasen bis zur Hölle. Jede gespielte Minute bringt Belohnungen und die Bosse kehren zurück.",
  "Nv {from} → Nv {to}": "Lv {from} → Lv {to}",
  "✖ ALTAR DE DESPIDO": "✖ ALTAR DER ENTLASSUNG",
  "Elige a quién echas del equipo. Pierdes sus técnicas y su parte de la vida, y su hueco queda libre para otro fichaje. El capitán no se puede echar.": "Wähle, wen du aus dem Team entlässt. Du verlierst seine Techniken und seinen Anteil am Leben, und sein Platz wird für einen anderen Transfer frei. Der Kapitän kann nicht entlassen werden.",
  "No echar a nadie": "Niemanden entlassen",
