  "Aguanta las oleadas de rivales hasta que llegue el jefe y derrótalo. Solo tu capitán recibe daño: si su vida llega a cero, pierdes (pero te quedas las monedas).": "Halte den Gegnerwellen stand, bis der Boss kommt, und besiege ihn. Nur dein Kapitän bekommt Schaden: Fällt sein Leben auf null, verlierst du (aber du behältst die Münzen).",
