  "Teclas 1, 2 y 3. Ofensiva: más daño y más riesgo. Equilibrada: neutra. Defensiva: menos daño recibido. Toca una:": "Tasten 1, 2 und 3. Offensiv: mehr Schaden und mehr Risiko. Ausgeglichen: neutral. Defensiv: weniger erlittener Schaden. Tippe auf eine:",
  "Objetos y experiencia": "Gegenstände und Erfahrung",
  "Chispa verde, balón azul y rayo dorado dan experiencia (de menos a más). La comida cura y los objetos especiales te ayudan un rato.": "Grüner Funke, blauer Ball und goldener Blitz geben Erfahrung (von wenig zu viel). Essen heilt und Spezialgegenstände helfen dir eine Weile.",
