  "{tokens} fichas · {x1} ◉ · una copia de sus tres estrellas · el marco del bando (la primera vez)": "{tokens} Marken · {x1} ◉ · eine Kopie seiner drei Stars · der Lager-Rahmen (beim ersten Mal)",
  "{tokens} fichas · {x1} ◉ si jugaste esa semana": "{tokens} Marken · {x1} ◉, wenn du in der Woche gespielt hast",
  "Semana {x1}": "Woche {x1}",
  "{x1}El bando es para toda la temporada y no se puede cambiar. Para que la lucha sea justa, el bando que vaya por delante en miembros no admite a nadie más hasta que el otro lo alcance. Cuentan las victorias de partidas normales (sin cooperativo, Road, clan ni entrenamiento).": "{x1}Das Lager gilt für die ganze Saison und kann nicht geändert werden. Damit es fair bleibt, nimmt das Lager, das bei den Mitgliedern vorn liegt, niemanden mehr auf, bis das andere aufgeholt hat. Es zählen Siege in normalen Runden (kein Koop, Road, Clan oder Training).",
  "Road to Fútbol Frontier: ahora Jaden sale a las 3 victorias en Máxima y otra copia cada 3. Por tus victorias recibes {x1}.": "Road to Football Frontier: Jaden kommt jetzt nach 3 Siegen auf Maximal und alle 3 eine weitere Kopie. Für deine Siege bekommst du {x1}.",
  "{x1} repeticiones borradas": "{x1} Replays gelöscht",
  "{rowsLength} repeticiones · {x1} en total. Cada jugador guarda sus 3 últimas y las de sus marcas del ranking.": "{rowsLength} Replays · {x1} insgesamt. Jeder Spieler behält seine letzten 3 und die seiner Ranglisten-Rekorde.",
  "{x1} · Nv {level}": "{x1} · Lv {level}",
  "Ficha a {who}": "Verpflichtet {who}",
