  "{x1} de {x2}": "{x1} von {x2}",
  "Sin vínculo especial con {pName}. Un compañero de historia, familia o técnica conjunta daría {x1}%.": "Keine besondere Bindung zu {pName}. Ein Story-Mitspieler, Familie oder eine gemeinsame Technik gäbe {x1} %.",
  "Bonificación = estadística del Aura × {x1}%, redondeada. Lo propio sigue en 99 como máximo; con el Aura, hasta {EFFECTIVE_STAT_MAX}.": "Bonus = Wert der Aura × {x1} %, gerundet. Eigene Werte bleiben bei maximal 99; mit der Aura bis {EFFECTIVE_STAT_MAX}.",
  "{x1} · {x2} · poder {power}": "{x1} · {x2} · Kraft {power}",
  "La primera empieza la partida en una ranura extra de Aura; la segunda puede aprenderse al subir de nivel. Golpean al {x1}% (son una técnica activa de más). No sustituyen a las suyas y desaparecen si quitas el Aura.": "Die erste startet die Runde in einem zusätzlichen Aura-Platz; die zweite kann man beim Aufsteigen lernen. Sie treffen mit {x1} % (sie sind eine aktive Technik mehr). Sie ersetzen nicht seine eigenen und verschwinden, wenn du die Aura entfernst.",
  "{x1} Afinidad de {x2}": "{x1} {x2}-Affinität",
  "Las técnicas de {pName} de elemento {x1} (también las heredadas) hacen <b>+{x2}%</b> de daño. {pName} sigue siendo de {x3} para todo lo demás.": "Die {x1}-Techniken von {pName} (auch geerbte) machen <b>+{x2} %</b> Schaden. {pName} bleibt für alles andere {x3}.",
  "y {x1} más · recógelos en Recompensas": "und {x1} mehr · hol sie dir unter Belohnungen",
