  "Jugadores de Fichatrón / Ojeadores: {x1} de {scoutsLength}. No pertenecen a un equipo de la historia, pero juegan igual que los demás.": "Transfertron-Spieler / Scouts: {x1} von {scoutsLength}. Sie gehören zu keinem Story-Team, spielen aber wie die anderen.",
