  "EVENTO · TERMINA EN {x1}": "EVENT · ENDET IN {x1}",
  "{x1} ◉ la tirada · Míticos al 3%": "{x1} ◉ pro Zug · Mythische zu 3 %",
  "DÍA {x1}{x2}": "TAG {x1}{x2}",
  "{x1} Si te saltas días no pierdes nada: el pase te espera.": "{x1} Wenn du Tage auslässt, verlierst du nichts: Der Pass wartet auf dich.",
  "{x1}{x2} · tras el día {PASSLength} empieza un ciclo nuevo": "{x1}{x2} · nach Tag {PASSLength} beginnt ein neuer Zyklus",
  "{x1} <b>{x2}</b>, y si llevas {min} o más jugadores de ese equipo en el campo, «Química de club»: +{x3}% de daño.": "{x1} <b>{x2}</b>, und wenn du {min} oder mehr Spieler dieses Teams auf dem Platz hast, „Club-Chemie“: +{x3} % Schaden.",
  "Posiciones distintas ({x1} / {x2}): la comparación es orientativa.": "Unterschiedliche Positionen ({x1} / {x2}): Der Vergleich ist nur ein Richtwert.",
  "Comparten equipo: {x1} (química de club con 3 o más en el campo).": "Sie teilen ein Team: {x1} (Club-Chemie mit 3 oder mehr auf dem Platz).",
  "Faltan duplicados: {x1} más": "Fehlende Duplikate: noch {x1}",
  "Faltan {x1} monedas": "Es fehlen {x1} Münzen",
  "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · daño ×{toFixed} · vida ×{toFixed2} · duplicados libres {sparesOf}": "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · Schaden ×{toFixed} · Leben ×{toFixed2} · freie Duplikate {sparesOf}",
  "✦ Elige {x1} de límite (+{STAR_CAP_STEP})": "✦ Wähle {x1} Limit (+{STAR_CAP_STEP})",
  "Toca una estadística por cada estrella: su límite sube +{STAR_CAP_STEP}. Puedes repetir la misma.{x1}": "Tippe für jeden Stern auf einen Wert: Sein Limit steigt um +{STAR_CAP_STEP}. Du kannst denselben wiederholen.{x1}",
  "{pName}: {done} {x1} de límite": "{pName}: {done} {x1} Limit",
  "★ Estrella de héroe ({sparesOf}/{x1})": "★ Heldenstern ({sparesOf}/{x1})",
  "▲ Ascensión ({sparesOf}/{x1})": "▲ Aufstieg ({sparesOf}/{x1})",
  "Maestría {x1}/{MASTERY_USESLength} · +{x2}% daño · {x3} usos": "Meisterschaft {x1}/{MASTERY_USESLength} · +{x2} % Schaden · {x3} Einsätze",
  "Estadísticas · media {statMean}{x1}": "Werte · Durchschnitt {statMean}{x1}",
  "(con su Aura {aeName}; propia {x1})": "(mit seiner Aura {aeName}; eigen {x1})",
  "COLABORACIÓN · TERMINA EN {x1}": "KOOPERATION · ENDET IN {x1}",
  "★ Destacada hoy: Épico ×{x1} · Legendario, Mítico y Leyenda ×{x2}": "★ Heute im Fokus: Episch ×{x1} · Legendär, Mythisch und Legende ×{x2}",
  "{x1}Precio y reglas": "{x1}Preis und Regeln",
  "Los futbolistas especiales solo salen aquí, con {x1} Comunes, Raros y Épicos de relleno. Se paga con fichas de evento: cada partida en Rango S o X te da tantas como fichas normales mientras dura el evento.": "Die Sonderspieler gibt es nur hier, mit {x1} Gewöhnlichen, Seltenen und Epischen als Füllung. Bezahlt wird mit Event-Marken: Jede Runde auf Rang S oder X gibt dir so viele wie normale Marken, solange das Event läuft.",
  "{x1}Tus {unit}": "{x1}Deine {unit}",
  "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (diez ×10 de golpe, un Épico o mejor asegurado en cada diez). {x4}{x5}": "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (zehn ×10 auf einmal, garantiert ein Episch oder besser pro zehn). {x4}{x5}",
  "Te llega para {x1} tirada(s).": "Reicht für {x1} Zug/Züge.",
  "{x1}Cómo conseguir fichas": "{x1}So bekommst du Marken",
  "{x1}Nuevo, duplicado y ascensión": "{x1}Neu, Duplikat und Aufstieg",
  "(hasta {MAX_STARS}): se compran con monedas en su ficha (10.000, 20.000… 50.000). Cada una da +{x1}% daño, +{x2}% vida y +5 al límite de la estadística que elijas. Los HÉROES y Campeones tienen 3 estrellas extra (100.000, 110.000 y 120.000).": "(bis zu {MAX_STARS}): Mit Münzen auf seiner Karte gekauft (10.000, 20.000… 50.000). Jeder gibt +{x1} % Schaden, +{x2} % Leben und +5 auf das Limit des Werts deiner Wahl. HELDEN und Champions haben 3 Extrasterne (100.000, 110.000 und 120.000).",
  "{x1}Probabilidades": "{x1}Wahrscheinlichkeiten",
  "{x1}: sin futbolistas por ahora; su probabilidad pasa a la rareza inferior.": "{x1}: vorerst keine Spieler; ihre Chance geht auf die Seltenheit darunter.",
  "{x1}Últimas tiradas": "{x1}Letzte Züge",
