  "Manual {lv}/{MAX_TECH_BOOST} · +{x1}% daño": "Handbuch {lv}/{MAX_TECH_BOOST} · +{x1} % Schaden",
  "Aparece sola en partida a partir del nivel {x1}; comprándola, desde el 1.": "Erscheint in der Runde von selbst ab Level {x1}; gekauft ab Level 1.",
  "{x1}Tu plantilla": "{x1}Dein Kader",
  "{x1} · {techniquesLength} técnicas": "{x1} · {techniquesLength} Techniken",
  "Máquina de cápsulas: gráficos de Inazuma Eleven 3 (LEVEL-5), hoja publicada en {x1}, ripeada por Avegaille.": "Kapselmaschine: Grafik aus Inazuma Eleven 3 (LEVEL-5), Sheet veröffentlicht auf {x1}, gerippt von Avegaille.",
  "Nombres en español e inglés de parte de las técnicas: {x1} (Fandom), contenido bajo {x2}.": "Spanische und englische Namen eines Teils der Techniken: {x1} (Fandom), Inhalt unter {x2}.",
  "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Herramienta: {x3} (MIT).": "Engine: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Tool: {x3} (MIT).",
  "Fuente: Press Start 2P © The Press Start 2P Project Authors ({x1}), vía Fontsource.": "Schrift: Press Start 2P © The Press Start 2P Project Authors ({x1}), über Fontsource.",
  "Ahora suena: {x1}. Por defecto suena la música de Inazuma Eleven exportada de tu copia. «Generada» usa temas creados para este proyecto.": "Läuft gerade: {x1}. Standardmäßig spielt die aus deiner Kopie exportierte Inazuma-Eleven-Musik. „Generiert“ nutzt für dieses Projekt erstellte Stücke.",
  "Vuelves a empezar como un jugador nuevo{x1}. No es lo mismo que eliminar la cuenta.": "Du fängst als neuer Spieler an{x1}. Das ist nicht dasselbe wie das Konto zu löschen.",
  "Tu progreso se guarda en este navegador.{x1}": "Dein Fortschritt wird in diesem Browser gespeichert.{x1}",
