  "Récord actual: {x1} en supervivencia infinita. Lo ganado se conserva al caer o al retirarte desde Pausa.": "Aktueller Rekord: {x1} im Endlos-Überleben. Was du verdienst, bleibt, wenn du fällst oder über Pause aufgibst.",
