  "Último golpe: {x1} de daño a los {x2} · Sobreviviste {timeSec}": "Letzter Treffer: {x1} Schaden bei {x2} · Du hast {timeSec} überlebt",
  "Tiempo extra {x1} · Fase alcanzada: {x2} · Jefes adicionales: {x3}": "Nachspielzeit {x1} · Erreichte Phase: {x2} · Zusätzliche Bosse: {x3}",
