  "elegido: toca una fila": "gewählt: tippe auf eine Reihe",
  "Es el último nivel: Campeón++": "Das ist das letzte Level: Champion++",
  "Marco dorado e insignia HÉROE en la colección": "Goldener Rahmen und HELDEN-Abzeichen in der Sammlung",
  "Termina en <b>{eventLeftText}</b>": "Endet in <b>{eventLeftText}</b>",
  "Pulsa": "Drück",
  "★ ACTIVO · Definitiva": "★ AKTIV · Ultimative",
  "con R": "mit R",
  "Capitán: <b>{capName}</b>": "Kapitän: <b>{capName}</b>",
  "Esperando a que <b>{partner}</b> elija la arena y empiece…": "Warte, bis <b>{partner}</b> die Arena wählt und startet…",
  "Mis depósitos": "Meine Angebote",
  ": otro dispositivo guardó una versión más nueva": ": Ein anderes Gerät hat eine neuere Version gespeichert",
  "Próximo gran premio: <b>{label}</b> · nivel {x1} {x2} · faltan {x3}": "Nächster großer Preis: <b>{label}</b> · Level {x1} {x2} · noch {x3}",
  "Ver el Sector": "Sektor ansehen",
  "El fútbol necesita orden. A partir de hoy, el Sector Quinto decide cómo se juega cada partido.": "Der Fußball braucht Ordnung. Ab heute entscheidet der Fünfte Sektor, wie jedes Spiel gespielt wird.",
  "Únete a nosotros… o intenta resistir. Cada semana veremos qué bando juega mejor.": "Schließ dich uns an… oder versuch Widerstand zu leisten. Jede Woche sehen wir, welches Lager besser spielt.",
  "Bienvenido al Sector Quinto. Aquí el fútbol se juega como yo digo.": "Willkommen im Fünften Sektor. Hier wird Fußball so gespielt, wie ich es sage.",
  "Acata mis decretos y tu bando ganará.": "Gehorche meinen Erlassen und dein Lager wird gewinnen.",
  "La Resistencia… Veremos cuánto aguanta vuestro viento.": "Der Widerstand… Mal sehen, wie lange euer Wind hält.",
  "Rebélate si quieres: el Sector Quinto también sabe jugar duro.": "Rebellier ruhig: Auch der Fünfte Sektor kann hart spielen.",
  "¡Llega {eName}!": "{eName} kommt!",
  "{x1} · {x2} rivales · Nv {level}": "{x1} · {x2} Gegner · Lv {level}",
  "sus estadísticas (Aura legendaria)": "seine Werte (legendäre Aura)",
  "Cada plaza de tu equipo tiene ahora una <b>{x1}</b> {x2} <b>{x3}</b>. Ahí pones a otro futbolista de tu colección para que apoye al de la plaza. El Aura no juega: lo potencia.": "Jeder Platz deines Teams hat jetzt eine <b>{x1}</b> {x2} <b>{x3}</b>. Dort setzt du einen anderen Spieler deiner Sammlung ein, der den Spieler auf dem Platz unterstützt. Die Aura spielt nicht: Sie verstärkt ihn.",
  "Solo pueden ser Aura los <b>Legendarios, Míticos y Leyendas</b>.": "Nur <b>Legendäre, Mythische und Legenden</b> können eine Aura sein.",
  "Una por futbolista. No se gasta nada: tu colección no cambia.": "Eine pro Spieler. Es wird nichts verbraucht: Deine Sammlung ändert sich nicht.",
  "El Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a las mismas del portador.": "Die Aura addiert <b>{x1} %</b> {x2} <b>{x3}</b> zu denselben Werten des Trägers.",
  "Ejemplo: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.": "Beispiel: Schuss 90 + Aura mit Schuss 95 » 90 + 14 = <b>104</b>.",
  "Lo propio sigue en 99 como máximo; con el Aura, hasta <b>120</b>, y en el combate se nota.": "Eigene Werte bleiben bei maximal 99; mit der Aura bis <b>120</b>, und das merkt man im Kampf.",
  "En el radar, lo que aporta el Aura se ve en <b style=\"color:#7ff6ff\">cian</b>.": "Auf dem Radar sieht man, was die Aura bringt, in <b style=\"color:#7ff6ff\">Cyan</b>.",
  "Si los dos tienen historia (técnica conjunta, amistad, familia o rivalidad), el Aura da el <b>{x1}%</b>{x2} <b>♥</b>.": "Haben die beiden eine gemeinsame Geschichte (gemeinsame Technik, Freundschaft, Familie oder Rivalität), gibt die Aura <b>{x1} %</b>{x2} <b>♥</b>.",
  "Axel y Shawn, Mark y Nathan, Jude y Celia, Arion y Riccardo...": "Axel und Shawn, Mark und Nathan, Jude und Celia, Arion und Riccardo...",
  "Estar en el mismo equipo no basta.": "Im selben Team zu sein reicht nicht.",
  "El portador hereda <b>{x1}</b> del Aura: una empieza la partida en una ranura extra y la otra llega como carta al subir de nivel. No sustituyen a las suyas.": "Der Träger erbt <b>{x1}</b> von der Aura: Eine startet die Runde in einem zusätzlichen Platz und die andere kommt beim Aufsteigen als Karte. Sie ersetzen nicht seine eigenen.",
  "Sus técnicas del elemento del Aura hacen <b>+{x1}%</b>.": "Seine Techniken vom Element der Aura machen <b>+{x1} %</b>.",
  "Con el Aura puede lanzar <b>{x1}</b>: Axel con Shawn de Aura, Fuego cruzado.": "Mit der Aura kann er <b>{x1}</b> einsetzen: Axel mit Shawn als Aura, Kreuzfeuer.",
  "Cómo equiparla:": "So rüstest du sie aus:",
  "toca «+ AURA» y elige en tu colección, o arrastra la carta encima.": "tippe auf „+ AURA“ und wähle aus deiner Sammlung, oder zieh die Karte darauf.",
  "Elige quién va a la <b>{x1}</b> ·": "Wähle, wer auf die <b>{x1}</b> kommt ·",
  "Ordenar: media": "Sortieren: Durchschnitt",
  "Ordenar: rareza": "Sortieren: Seltenheit",
