  "Juntos lanzan Lluvia oscura.": "Zusammen entfesseln sie Zwielicht.",
  "Hermanos: juntos lanzan Grito del Edén.": "Geschwister: Zusammen entfesseln sie Schrei von Eden.",
  "Con Jude lanzan Pingüino emperador n.º 3.": "Mit Jude entfesseln sie Kaiserpinguin III.",
  "Hermanos: Axel juega por Julia desde que ella se recuperó del accidente.": "Geschwister: Axel spielt für Julia, seit sie sich von dem Unfall erholt hat.",
  "Gerente y capitán del Raimon; en GO ya son marido y mujer.": "Raimons Managerin und Kapitän; in GO sind sie verheiratet.",
  "Mark adulto y Nelly están casados.": "Der erwachsene Mark und Nelly sind verheiratet.",
  "Mark adulto entrena al Raimon de Arion y le enseña a amar el fútbol.": "Der erwachsene Mark trainiert Arions Raimon und lehrt ihn, den Fußball zu lieben.",
  "Darren admira a Mark y hereda su Mano mágica como portero del Raimon.": "Darren bewundert Mark und erbt als Raimons Torwart seine Magische Hand.",
  "Amigos de la infancia en Estados Unidos, con Bobby.": "Kindheitsfreunde in den USA, mit Bobby.",
  "Amigos de la infancia en Estados Unidos, con Erik.": "Kindheitsfreunde in den USA, mit Erik.",
  "Crecieron juntos en el orfanato Sun Garden y capitanearon la Academia Alius.": "Sie sind zusammen im Waisenhaus Sun Garden aufgewachsen und waren Kapitäne der Alius-Akademie.",
  "Amigos del orfanato Sun Garden; juntos en Inazuma Japón.": "Freunde aus dem Waisenhaus Sun Garden; zusammen bei Inazuma Japan.",
  "Inseparables del Royal Academy, también en el Instituto Imperial.": "Unzertrennlich in der Royal Academy und auch bei Shin Teikoku.",
  "Capitán y portero del Royal Academy de Ray Dark.": "Kapitän und Torwart von Ray Darks Royal Academy.",
  "Ray Dark lo crió como su estratega en el Royal; Jude acabó enfrentándose a él.": "Ray Dark hat ihn bei Royal zu seinem Strategen gemacht; am Ende stellte sich Jude gegen ihn.",
  "Tío y sobrino: Lucian juega para limpiar el nombre de los Dark.": "Onkel und Neffe: Lucian spielt, um den Namen Dark reinzuwaschen.",
